# -*- coding: utf-8 --
from robot.api import logger
from taf.nms.netact import netact
# from taf.ul.oam.netact.cm import cm
# from taf.ul.oam.netact.swm import swm
from taf.rfrl.cbts.utilities import tl_config
from robot.libraries.BuiltIn import BuiltIn

LOG_HEAD = LOG_END = '*' * 8
builtin_obj = BuiltIn()


class GenericNetAct(object):
    netact_taf = netact()
    # netact_ul_cm = cm()
    # netact_ul_swm = swm()

    # SUPPORTED_SERVICES = ('cmwas', 'fmwas')

    def __init__(self):

        self.selected = False
        self.web_url = None
        self.web_username = None
        self.web_password = None

        self.hostname = None
        self.ssh_username = None
        self.ssh_password = None

    def _try_add_node_to_netact(self, netact_ssh_credentials):
        try:
            self.netact_taf.add_node(service_name='cmwas',
                                     hostname=netact_ssh_credentials['addr'],
                                     username=netact_ssh_credentials['username'],
                                     password=netact_ssh_credentials['password'])
            self.selected = True
        except Exception:
            logger.warn('{} Netact {} can not be reachable, try the next one {}'.format(
                LOG_HEAD, netact_ssh_credentials['addr'], LOG_END))
        finally:
            self.netact_taf.delete_node('cmwas')

    def _select_available_netact_via_global_variable(self, netact_index, netact_info, netact_candidate=None):
        netact_rest_credentials = None
        netact_ssh_credentials = None
        netact_amount = len(netact_info)

        if netact_index is not None:
            try:   # for pass netact_index like clab1013
                netact_index = int(netact_index)
            except Exception:
                for index in range(len(netact_info)):
                    if netact_index == netact_info[index]['netact_id']:
                        netact_index = index
                        break
            netact_rest_credentials = {
                'addr': netact_info[int(netact_index)]['url'],
                'username': netact_info[int(netact_index)]['url_user'],
                'password': netact_info[int(netact_index)]['url_password']}
            netact_ssh_credentials = {
                'addr': netact_info[int(netact_index)]['node_ip'],
                'username': netact_info[int(netact_index)]['user'],
                'password': netact_info[int(netact_index)]['password']}
            self._try_add_node_to_netact(netact_ssh_credentials)
            if not self.selected:
                raise Exception('The given Netact can not be reached, please check the passed netact index')
        else:
            for index in range(netact_amount):
                netact_rest_credentials = {
                    'addr': netact_info[index]['url'], 'username': netact_info[index]['url_user'],
                    'password': netact_info[index]['url_password']}
                netact_ssh_credentials = {
                    'addr': netact_info[index]['node_ip'], 'username': netact_info[index]['user'],
                    'password': netact_info[index]['password']}
                if netact_candidate:
                    if netact_candidate in netact_info[index]['tag']:
                        self._try_add_node_to_netact(netact_ssh_credentials)
                        if self.selected:
                            break
                    else:
                        continue
                else:
                    self._try_add_node_to_netact(netact_ssh_credentials)
                    if self.selected:
                        break
            if not self.selected:
                raise Exception('None of the Netact is available in global_variable file, '
                                'please check the configuration.')
        return netact_rest_credentials, netact_ssh_credentials

    def _select_available_netact_via_init_file(self, netact_index):
        netact_rest_credentials = netact_ssh_credentials = None
        netact_amount = tl_config.get_the_number_of_netact()
        if netact_index:
            netact_rest_credentials = tl_config.get_netact_rest_credentials(int(netact_index))
            netact_ssh_credentials = tl_config.get_netact_ssh_credentials(int(netact_index))
            self._try_add_node_to_netact(netact_ssh_credentials)
            if not self.selected:
                raise Exception('The given Netact can not be reached, please check the passed netact index.')
        else:
            for netact_index in range(netact_amount):
                netact_ssh_credentials = tl_config.get_netact_ssh_credentials(netact_index)
                netact_rest_credentials = tl_config.get_netact_rest_credentials(netact_index)
                self._try_add_node_to_netact(netact_ssh_credentials)
                if self.selected:
                    break
            if not self.selected:
                raise Exception('None of the Netact is available in init file, please check the configuration.')
        return netact_rest_credentials, netact_ssh_credentials

    def select_available_netact(self, netact_index=None):
        netact_info = builtin_obj.get_variable_value("${ALL_NETACTs_INFO}")
        netact_candidate = builtin_obj.get_variable_value("${NETACT_SERVER_CANDIDATE}")
        if netact_info:
            logger.info('{} select netact from global_variable.py {}'.format(LOG_HEAD, LOG_END))
            netact_rest_credentials, netact_ssh_credentials = \
                self._select_available_netact_via_global_variable(netact_index, netact_info, netact_candidate)
        else:
            logger.info('{} select netact from __init__.py {}'.format(LOG_HEAD, LOG_END))
            netact_rest_credentials, netact_ssh_credentials = self._select_available_netact_via_init_file(netact_index)

        logger.info('{} netact credetials are {} {} {}'.format(LOG_HEAD, netact_rest_credentials,
                                                               netact_ssh_credentials, LOG_END))

        self.web_url = netact_rest_credentials['addr']
        self.web_username = netact_rest_credentials['username']
        self.web_password = netact_rest_credentials['password']

        self.hostname = netact_ssh_credentials['addr']
        self.ssh_username = netact_ssh_credentials['username']
        self.ssh_password = netact_ssh_credentials['password']

    def setup_netact_by_taf(self, service_name):
        """

        :param str service_name: "cmwas"
        :return:
        """
        self.netact_taf.add_web_url(web_url=self.web_url,
                                    username=self.web_username,
                                    password=self.web_password)

        if service_name:
            self.netact_taf.add_node(service_name=service_name,
                                     hostname=self.hostname,
                                     username=self.ssh_username,
                                     password=self.ssh_password)

    def cleanup_netact_by_taf(self, service_name):
        if service_name:
            self.netact_taf.delete_node(service_name)
        self.netact_taf.clean_all()

